from starlette._utils import parse_host_authority, parse_host_header
from starlette.datastructures import URL

values = ['example.com', 'example.com:00080', 'example.com:65535', 'example.com:65536', '[::1]', '[::1]:00080', '[v1.fe80]', '[vF.a:b]:9', '[gg::1]', 'x:bad', 'x:', 'x/y', 'x%2Fy', 'x%xy']
